/**
 * Source for the inline `subagent-artifact` CLI helper.
 *
 * The launch script generated by interactive-tmux.ts writes this script body
 * to `$ARTIFACT_DIR/cli.mjs` (via a heredoc) and invokes it for lifecycle
 * events. The wrapper's EXIT trap records process exit and a completion if
 * needed; the child pi process writes `done` / `error` itself.
 *
 * Keeping the source as a single string means there's no build step, no
 * extra file in the published package, and no path-resolution concerns when
 * the extension is loaded from arbitrary cwd's.
 *
 * Subcommands:
 *   done <exitCode>             — write a `done` event with the child's exit code
 *   error "<message>"           — write an `error` event
 *   cancelled                   — write a `cancelled` event
 *   process-exit <exitCode>     — record process exit and, when needed, completion
 *
 * Exit codes: 0 on success, 2 on usage error (missing env var / unknown cmd).
 */

import {
  MAX_ACTIVE_TOOL_ID_LENGTH,
  MAX_ACTIVE_TOOL_RECORDS,
  MAX_ACTIVE_TURN_BYTES,
  MAX_EVENT_TEXT_LENGTH,
  MAX_OUTPUT_SNAPSHOT_BYTES,
  MAX_TOOL_NAME_LENGTH,
  MAX_TURN_ID_LENGTH,
} from "./artifact";

/**
 * The body of the CLI as a string, written verbatim to
 * `$ARTIFACT_DIR/cli.mjs` by `writeLaunchScript`. The string is the literal
 * JavaScript the child process executes.
 */
export const CLI_SOURCE = String.raw`#!/usr/bin/env node
// Generated by pi-subagentura. Writes v2 lifecycle events to the artifact
// directory (\$ARTIFACT_DIR). Subcommands: done, error, cancelled, process-exit.
// See subagent-artifact-cli.ts for the source.
import {
  appendFileSync,
  closeSync,
  constants,
  existsSync,
  fstatSync,
  mkdirSync,
  openSync,
  readFileSync,
  readSync,
  realpathSync,
  renameSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { createHash, randomUUID } from "node:crypto";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

export function reportPromptError(turnId, message, previousUserEntryId) {
  runCli({ promptError: { turnId, message, previousUserEntryId } });
}

function runCli(options = {}) {
const dir = process.env.ARTIFACT_DIR;
if (!dir) {
  if (options.promptError) throw new Error("ARTIFACT_DIR not set");
  process.stderr.write("ARTIFACT_DIR not set\n");
  process.exitCode = 2;
  return;
}
mkdirSync(dir, { recursive: true, mode: 0o700 });

const statusFile = join(dir, "events.ndjson");
const activeTurnFile = join(dir, "active-turn.json");
const MAX_OUTPUT_SNAPSHOT_BYTES = ${MAX_OUTPUT_SNAPSHOT_BYTES};
const MAX_EVENT_TEXT_LENGTH = ${MAX_EVENT_TEXT_LENGTH};
const MAX_ACTIVE_TURN_BYTES = ${MAX_ACTIVE_TURN_BYTES};
const MAX_ACTIVE_TOOL_RECORDS = ${MAX_ACTIVE_TOOL_RECORDS};
const MAX_ACTIVE_TOOL_ID_LENGTH = ${MAX_ACTIVE_TOOL_ID_LENGTH};
const MAX_TOOL_NAME_LENGTH = ${MAX_TOOL_NAME_LENGTH};
const MAX_TURN_ID_LENGTH = ${MAX_TURN_ID_LENGTH};
const boundedOptionalEventText = (value) =>
  typeof value === "string" ? value.slice(0, MAX_EVENT_TEXT_LENGTH) : undefined;
const SAFE_METADATA_PATTERN = /^[A-Za-z0-9._:-]+$/;
const boundedMetadataIdentifier = (value, maxLength) =>
  typeof value === "string" &&
  value.length > 0 &&
  value.length <= maxLength &&
  SAFE_METADATA_PATTERN.test(value)
    ? value
    : undefined;

const cmd = process.argv[2];
const arg = process.argv[3];
const write = (obj) => appendFileSync(statusFile, JSON.stringify(obj) + "\n", { mode: 0o600 });
const readEvents = () => {
  try {
    return readFileSync(statusFile, "utf8")
      .split("\n")
      .filter(Boolean)
      .flatMap((line) => {
        try { return [JSON.parse(line)]; } catch { return []; }
      });
  } catch {
    return [];
  }
};
const normalizeActiveTool = (value) => {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const name = boundedMetadataIdentifier(value.name, MAX_TOOL_NAME_LENGTH);
  const callId = boundedMetadataIdentifier(value.callId, MAX_ACTIVE_TOOL_ID_LENGTH);
  if (!name || !Number.isSafeInteger(value.startedAt) || value.startedAt < 0) return null;
  return { name, ...(callId ? { callId } : {}), startedAt: value.startedAt };
};
const activeTurnMetadata = () => {
  let fd;
  try {
    fd = openSync(activeTurnFile, constants.O_RDONLY | constants.O_NOFOLLOW);
    const metadata = fstatSync(fd);
    if (!metadata.isFile() || metadata.size > MAX_ACTIVE_TURN_BYTES) return null;
    const buffer = Buffer.alloc(metadata.size);
    let offset = 0;
    while (offset < metadata.size) {
      const bytesRead = readSync(
        fd,
        buffer,
        offset,
        metadata.size - offset,
        offset,
      );
      if (bytesRead <= 0) return null;
      offset += bytesRead;
    }
    const value = JSON.parse(buffer.toString("utf8"));
    if (!value || typeof value !== "object" || Array.isArray(value)) return null;
    const turnId = boundedMetadataIdentifier(value.turnId, MAX_TURN_ID_LENGTH);
    if (!turnId) return null;
    if (Array.isArray(value.activeTools) && value.activeTools.length > MAX_ACTIVE_TOOL_RECORDS) return null;
    const activeTools = Array.isArray(value.activeTools)
      ? value.activeTools.map(normalizeActiveTool).filter(Boolean)
      : [];
    const lastTool = boundedMetadataIdentifier(value.lastTool, MAX_TOOL_NAME_LENGTH);
    return {
      turnId,
      started: value.started === true,
      activeTools,
      ...(lastTool ? { lastTool } : {}),
    };
  } catch {
    return null;
  } finally {
    if (fd !== undefined) {
      try { closeSync(fd); } catch { /* bounded metadata is no longer usable */ }
    }
  }
};
const activeState = activeTurnMetadata();
const turnId = activeState?.turnId ?? "process";
const lockWaiter = new Int32Array(new SharedArrayBuffer(4));
const withCompletionLock = (targetTurnId, operation) => {
  const lockKey = createHash("sha256").update(targetTurnId).digest("hex").slice(0, 24);
  const completionLock = join(dir, ".completion-" + lockKey + ".lock");
  const deadline = Date.now() + 2000;
  while (true) {
    try {
      mkdirSync(completionLock, { mode: 0o700 });
      break;
    } catch (error) {
      if (error?.code !== "EEXIST") throw error;
      try {
        if (Date.now() - statSync(completionLock).mtimeMs > 30000) {
          rmSync(completionLock, { recursive: true, force: true });
          continue;
        }
      } catch {
        continue;
      }
      if (Date.now() >= deadline) {
        throw new Error("timed out acquiring completion lock for " + targetTurnId);
      }
      Atomics.wait(lockWaiter, 0, 0, 10);
    }
  }
  try {
    return operation();
  } finally {
    rmSync(completionLock, { recursive: true, force: true });
  }
};
const completed = (targetTurnId) =>
  readEvents().some((event) =>
    event.version === 2 && event.type === "completion" && event.turnId === targetTurnId);
const signalNames = [
  undefined,
  "SIGHUP",
  "SIGINT",
  "SIGQUIT",
  "SIGILL",
  "SIGTRAP",
  "SIGABRT",
  "SIGBUS",
  "SIGFPE",
  "SIGKILL",
  "SIGUSR1",
  "SIGSEGV",
  "SIGUSR2",
  "SIGPIPE",
  "SIGALRM",
  "SIGTERM",
  "SIGCHLD",
  "SIGCONT",
  "SIGSTOP",
  "SIGTSTP",
  "SIGTTIN",
  "SIGTTOU",
  "SIGURG",
  "SIGXCPU",
  "SIGXFSZ",
  "SIGVTALRM",
  "SIGPROF",
  "SIGWINCH",
  "SIGIO",
  "SIGPWR",
  "SIGSYS",
  ];
const signalForExitCode = (exitCode) => {
  const signalNumber = exitCode - 128;
  return Number.isSafeInteger(exitCode) && signalNumber > 0 && signalNumber < signalNames.length
    ? signalNames[signalNumber]
    : undefined;
};
const processExitDiagnostics = (exitCode, cancelled, alreadyCompleted) => {
  const activeTool = activeState?.activeTools?.at(-1);
  const signal = signalForExitCode(exitCode);
  const terminationReason = alreadyCompleted
    ? "normal_exit"
    : cancelled
      ? "cancelled"
      : activeTool
        ? "active_tool"
        : activeState?.started
          ? "active_turn"
          : signal
            ? "signal"
            : exitCode === 0
              ? "unknown"
              : "nonzero_exit";
  return {
    terminationReason,
    ...(signal ? { signal } : {}),
    ...(!alreadyCompleted && (activeTool?.name ?? activeState?.lastTool)
      ? { lastTool: activeTool?.name ?? activeState?.lastTool }
      : {}),
  };
};
const snapshot = (eventId) => {
  const source = join(dir, "output.md");
  let fd;
  let content;
  try {
    fd = openSync(source, constants.O_RDONLY | constants.O_NOFOLLOW);
    const stat = fstatSync(fd);
    if (!stat.isFile()) {
      return { outputError: { code: "output_unavailable", message: "output.md is not a regular file" } };
    }
    if (stat.size > MAX_OUTPUT_SNAPSHOT_BYTES) {
      return {
        outputError: {
          code: "output_too_large",
          bytes: stat.size,
          maxBytes: MAX_OUTPUT_SNAPSHOT_BYTES,
        },
      };
    }
    content = Buffer.alloc(stat.size);
    let offset = 0;
    while (offset < content.length) {
      const bytesRead = readSync(fd, content, offset, content.length - offset, offset);
      if (bytesRead === 0) break;
      offset += bytesRead;
    }
    content = content.subarray(0, offset);
  } catch (error) {
    if (error?.code === "ENOENT") return {};
    return { outputError: { code: "output_unavailable", message: "output.md could not be read safely" } };
  } finally {
    if (fd !== undefined) {
      try { closeSync(fd); } catch { /* bounded content is already in memory */ }
    }
  }
  const outputs = join(dir, "outputs");
  mkdirSync(outputs, { recursive: true, mode: 0o700 });
  const target = join(outputs, eventId + ".md");
  if (!existsSync(target)) {
    const tmp = target + ".tmp";
    writeFileSync(tmp, content, { mode: 0o600 });
    renameSync(tmp, target);
  }
  return {
    output: {
      path: target,
      bytes: content.byteLength,
      sha256: createHash("sha256").update(content).digest("hex"),
    },
  };
};
const emptySnapshot = (eventId) => {
  const content = Buffer.alloc(0);
  const outputs = join(dir, "outputs");
  mkdirSync(outputs, { recursive: true, mode: 0o700 });
  const target = join(outputs, eventId + ".md");
  if (!existsSync(target)) {
    const tmp = target + ".tmp";
    writeFileSync(tmp, content, { mode: 0o600 });
    renameSync(tmp, target);
  }
  return {
    output: {
      path: target,
      bytes: 0,
      sha256: createHash("sha256").update(content).digest("hex"),
    },
  };
};
const appendCompletion = (targetTurnId, outcome, source, extra, makeSnapshot) => {
  if (completed(targetTurnId)) return false;
  const eventId = randomUUID();
  const snapshotResult = makeSnapshot(eventId);
  write({
    version: 2,
    eventId,
    turnId: targetTurnId,
    ts: Date.now(),
    type: "completion",
    status: outcome,
    outcome,
    source,
    ...snapshotResult,
    ...extra,
  });
  return true;
};
const completionFor = (targetTurnId, outcome, source, extra = {}) =>
  withCompletionLock(targetTurnId, () =>
    appendCompletion(targetTurnId, outcome, source, extra, snapshot));
const completion = (outcome, source, extra = {}) =>
  completionFor(turnId, outcome, source, extra);
const writePromptErrorActiveTurn = (targetTurnId, previousUserEntryId) => {
  const payload = JSON.stringify({
    turnId: targetTurnId,
    startedAt: Date.now(),
    started: false,
    ...(previousUserEntryId ? { previousUserEntryId } : {}),
    activeTools: [],
  });
  if (Buffer.byteLength(payload, "utf8") > MAX_ACTIVE_TURN_BYTES) {
    throw new Error("prompt error active-turn metadata exceeds its size limit");
  }
  const tmp = activeTurnFile + "." + randomUUID() + ".tmp";
  let fd;
  try {
    fd = openSync(
      tmp,
      constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | constants.O_NOFOLLOW,
      0o600,
    );
    writeFileSync(fd, payload);
    closeSync(fd);
    fd = undefined;
    renameSync(tmp, activeTurnFile);
  } catch (error) {
    if (fd !== undefined) {
      try { closeSync(fd); } catch { /* preserve the metadata write error */ }
    }
    try { rmSync(tmp, { force: true }); } catch { /* preserve the metadata write error */ }
    throw error;
  }
};
if (options.promptError) {
  const request = options.promptError;
  const promptTurnId = boundedMetadataIdentifier(request.turnId, MAX_TURN_ID_LENGTH);
  if (!promptTurnId) throw new TypeError("prompt error turnId is not a valid Pi entry ID");
  const previousUserEntryId =
    request.previousUserEntryId === undefined
      ? undefined
      : boundedMetadataIdentifier(request.previousUserEntryId, MAX_TURN_ID_LENGTH);
  if (request.previousUserEntryId !== undefined && !previousUserEntryId) {
    throw new TypeError("previousUserEntryId is not a valid Pi entry ID");
  }
  const errorMessage =
    typeof request.message === "string"
      ? request.message.slice(0, MAX_EVENT_TEXT_LENGTH)
      : String(request.message).slice(0, MAX_EVENT_TEXT_LENGTH);
  withCompletionLock(promptTurnId, () => {
    if (existsSync(join(dir, ".cancelled"))) return;
    if (appendCompletion(
      promptTurnId,
      "error",
      "prompt_error",
      { exitCode: 1, message: errorMessage, errorMessage },
      emptySnapshot,
    )) {
      writePromptErrorActiveTurn(promptTurnId, previousUserEntryId);
    }
  });
  return;
}

switch (cmd) {
  case "done": {
    const exitCode = Number(arg ?? 0);
    completion(exitCode === 0 ? "done" : "error", "explicit", { exitCode });
    break;
  }
  case "error":
    const errorMessage = boundedOptionalEventText(arg ?? "unknown error");
    completion("error", "explicit", {
      ...(errorMessage ? { message: errorMessage, errorMessage } : {}),
    });
    break;
  case "cancelled":
    completion("cancelled", "parent");
    break;
  case "process-exit": {
    const exitCode = Number(arg ?? 0);
    const cancelled = existsSync(join(dir, ".cancelled"));
    const alreadyCompleted = completed(turnId);
    const diagnostics = processExitDiagnostics(
      exitCode,
      cancelled,
      alreadyCompleted,
    );
    if (!alreadyCompleted) {
      completion(cancelled ? "cancelled" : "error", "process_exit", {
        exitCode,
        ...(!cancelled ? { message: "sub-agent process exited before turn completion" } : {}),
      });
    }
    write({
      version: 2,
      eventId: randomUUID(),
      turnId,
      ts: Date.now(),
      type: "process_exited",
      status: cancelled ? "cancelled" : exitCode === 0 ? "done" : "error",
      exitCode,
      ...diagnostics,
    });
    break;
  }
  default:
    process.stderr.write("Unknown command: " + cmd + "\n");
    process.exit(2);
}

}
const isDirectEntry = () => {
  if (!process.argv[1]) return false;
  try {
    return realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
};
if (isDirectEntry()) runCli();
`;

/** Test-only helper: write the CLI to a file and chmod it. */
export function writeCliScript(targetPath: string): void {
  const { writeFileSync, chmodSync } =
    require("node:fs") as typeof import("node:fs");
  writeFileSync(targetPath, CLI_SOURCE, { mode: 0o700 });
  chmodSync(targetPath, 0o700);
}
